@router.post("/api/v1/inventory/reallocate-bin")
async def reallocate_stock_bin(
    payload: BinTransferRequest,
    current_user: User = Depends(get_current_user)
):
    async with warehouse_transaction_scope() as tx:
        source_bin = await tx.fetch_bin(payload.source_bin_id, lock=True)
        if not source_bin or source_bin.merchant_id != current_user.merchant_id:
            raise HTTPException(status_code=404, detail="Source bin not found or not owned by merchant")
        if source_bin.quantity < payload.quantity:
            raise HTTPException(status_code=400, detail="Insufficient stock in source bin")
        destination_bin = await tx.fetch_bin(payload.destination_bin_id, lock=True)
        if not destination_bin or destination_bin.merchant_id != current_user.merchant_id:
            raise HTTPException(status_code=403, detail="Destination bin not owned by merchant")
        await tx.deduct_inventory(source_bin.id, payload.quantity)
        await tx.add_inventory(destination_bin.id, payload.quantity)
        await tx.record_transfer_log(source_bin.id, destination_bin.id, payload.quantity)
    return {"transferred": True}
